data.code:
param keyVaultName string
param location string = resourceGroup().location
param subnetId string

resource keyVault 'Microsoft.KeyVault/vaults@2023-07-01' existing = {
  name: keyVaultName
}

resource privateEndpoint 'Microsoft.Network/privateEndpoints@2023-09-01' = {
  name: '${keyVaultName}-pe'
  location: location
  properties: {
    subnet: {
      id: subnetId
    }
    privateLinkServiceConnections: [
      {
        name: 'keyvault-connection'
        properties: {
          privateLinkServiceId: keyVault.id
          groupIds: [
            'vault'
          ]
        }
      }
    ]
  }
}

resource privateDnsZone 'Microsoft.Network/privateDnsZones@2023-09-01' existing = {
  name: 'privatelink.vaultcore.azure.net'
}

resource dnsZoneGroup 'Microsoft.Network/privateEndpoints/privateDnsZoneGroups@2023-09-01' = {
  name: '${privateEndpoint.name}/default'
  properties: {
    privateDnsZoneConfigs: [
      {
        name: 'vault-dns'
        properties: {
          privateDnsZoneId: privateDnsZone.id
          recordSets: {
            '${keyVaultName}': {
              fqdn: keyVault.properties.vaultUri
              ipAddresses: [
                privateEndpoint.properties.networkInterfaces[0].id
              ]
            }
          }
        }
      }
    ]
  }
}
